7	// 设备停用与恢复使用。
8	//
9	// 停用：仅“可用”（无未关闭工单、未停用）的资产可以停用，输入资产编号与非空
10	// 理由；维修中（存在未关闭工单）的资产不能停用。成功后资产状态变为“停用”，
11	// 追加一条资产级履历，记录操作时间、原状态、新状态与理由。停用不创建工单、
12	// 不消耗工单编号，不删除工单、负责人、备件或附件记录，也不改变保养内容、
13	// 间隔或下一到期日，不暂停或重算保养周期。
14	//
15	// 恢复使用：仅停用资产可恢复，输入资产编号与非空理由。成功后资产状态恢复
16	// “可用”，同样追加一条含原状态、新状态、理由与操作时间的资产级履历。历史
17	// 记录不因恢复而删除；恢复后按保存的下一到期日参与到期查询。
18	//
19	// 停用期间拒绝新报修与保养完成登记，但已有报修请求的相同重放仍返回原工单及
20	// 当前状态，不开单、不改资产状态；停用资产仍可建立保养计划、撤销已登记完成，
21	// 终态工单仍可补充或撤销附件。停用、恢复各为一次原子保存：校验、履历容量或
22	// 读写失败时保留原文件字节，不留下部分状态或履历，不消耗序号，恢复后可重试。
23	
24	// appendStatusEvent 以给定序号追加停用/恢复使用履历。该履历为资产级履历，
25	// 不属于任何工单；from/to 为原资产状态与新资产状态，content 为理由。
26	func (s *store) appendStatusEvent(seq int, assetID, kind, from, to, reason string) {
27		s.data.Events = append(s.data.Events, Event{
28			Seq:     seq,
29			AssetID: assetID,
30			Kind:    kind,
31			Content: reason,
32			From:    from,
33			To:      to,
34			Time:    s.now(),
35		})
36	}
37	
38	// deactivateAsset 停用资产：仅“可用”且无未关闭工单的资产可停用。
39	// 未知资产、空理由、重复停用、维修中停用均拒绝。失败路径不修改任何业务数据。
40	func (s *store) deactivateAsset(assetID, reason string) (*Asset, error) {
41		a := s.findAsset(assetID)
42		if a == nil {
43			return nil, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
44		}
45		if reason == "" {
46			return nil, fmt.Errorf("%w: 停用理由不能为空", errConflict)
47		}
48		if a.Status == statusDeactivated {
49			return nil, fmt.Errorf("%w: 资产 %s 已停用，不能重复停用", errConflict, assetID)
50		}
51		if t := s.openTicketOf(assetID); t != nil {
52			return nil, fmt.Errorf("%w: 资产 %s 有未关闭工单 %s，维修中不能停用", errConflict, assetID, t.ID)
53		}
54		if a.Status != statusAvailable {
55			return nil, fmt.Errorf("%w: 资产 %s 当前状态为 %s，不能停用", errConflict, assetID, a.Status)
56		}
57		eventSeq, err := s.nextEventSeq()
58		if err != nil {
59			return nil, err
60		}
61		from := a.Status
62		a.Status = statusDeactivated
63		s.appendStatusEvent(eventSeq, assetID, eventDeactivate, from, statusDeactivated, reason)
64		return a, nil
65	}
66	
67	// reactivateAsset 恢复使用停用资产：仅停用资产可恢复，理由非空。
68	// 未知资产、空理由、对可用或维修中资产恢复均拒绝。失败路径不修改任何业务数据。
69	func (s *store) reactivateAsset(assetID, reason string) (*Asset, error) {
