72			return nil, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
73		}
74		if reason == "" {
75			return nil, fmt.Errorf("%w: 恢复理由不能为空", errConflict)
76		}
77		if a.Status == statusAvailable {
78			return nil, fmt.Errorf("%w: 资产 %s 未停用，不能恢复使用", errConflict, assetID)
79		}
80		if t := s.openTicketOf(assetID); t != nil {
81			return nil, fmt.Errorf("%w: 资产 %s 有未关闭工单 %s，不能恢复使用", errConflict, assetID, t.ID)
82		}
83		if a.Status != statusDeactivated {
84			return nil, fmt.Errorf("%w: 资产 %s 当前状态为 %s，不能恢复使用", errConflict, assetID, a.Status)
85		}
86		eventSeq, err := s.nextEventSeq()
87		if err != nil {
88			return nil, err
89		}
90		from := a.Status
91		a.Status = statusAvailable
