1	package main
2	
3	import (
4		"archive/zip"
5		"bytes"
6		"crypto/sha256"
7		"encoding/hex"
8		"encoding/json"
9		"errors"
10		"flag"
11		"fmt"
12		"io"
13		"os"
14		"path/filepath"
15		"regexp"
16		"sort"
17		"strings"
18	)
19	
20	// 离线资产迁移包：把所选资产及其全部关联数据连同每条附件索引指向的资料
21	// 文件内容打包为单个 .zip 迁移包（export），日后可在尚不存在的新数据目录
22	// 整包还原（restore），还原后资料为目标目录内的独立副本，脱离源目录。
23	//
24	// 设计约束（与全工具一致）：仅用 Go 标准库；单进程顺序调用；不依赖任何
25	// 外部服务；源台账与原资料只读；失败不留成品包或目标目录，输入字节保持，
26	// 恢复条件后可用原包重试。
27	//
28	// 包内布局（全部为普通文件成员，不允许目录、链接，不允许越界成员名）：
29	//
30	//	caretrack.json          所选数据的台账（storeData 的 JSON，与日常保存同构）
31	//	files/f000001 ...       资料文件内容，每条附件索引一个独立成员
32	//	manifest.json           清单：包格式版本、台账与每份资料的大小及 SHA-256
33	//
34	// 同一路径的多条附件索引各占一个成员，保持独立；已撤销索引的资料同样打包。
35	// 资料成员名是包内生成名，与资料原路径无关；原绝对路径只存在于台账记录中，
36	// 还原时不会按它访问外部任何文件。
37	const (
38		migrateMagic        = "caretrack-migration-package"
39		migrateVersion      = 1
40		migrateManifestName = "manifest.json"
41		migrateLedgerName   = dataFileName
42		migrateFilesDir     = "files"
43		// restoreAttachDir 是还原后目标数据目录内资料副本所在的子目录。
44		restoreAttachDir = "attachments"
45	)
46	
47	// migrateFileMeta 描述包内一个资料成员与一条附件索引的映射及内容校验值。
48	type migrateFileMeta struct {
49		AttachmentID string `json:"attachment_id"`
50		Member       string `json:"member"`
51		Size         int64  `json:"size"`
52		SHA256       string `json:"sha256"`
53	}
54	
55	// migrateManifest 为迁移包清单：台账与每份资料的内容校验值，以及汇总数量。
56	type migrateManifest struct {
57		Format          string            `json:"format"`
58		Version         int               `json:"version"`
59		Ledger          string            `json:"ledger"`
60		LedgerSize      int64             `json:"ledger_size"`
61		LedgerSHA256    string            `json:"ledger_sha256"`
62		Files           []migrateFileMeta `json:"files"`
63		AssetCount      int               `json:"asset_count"`
64		AttachmentCount int               `json:"attachment_count"`
65	}
66	
67	// exportOutcome 为一次成功打包的结果摘要。
68	type exportOutcome struct {
69		packagePath string
70		assetIDs    []string
71		attachments int
72	}
73	
74	// restoreOutcome 为一次成功还原的结果摘要。
75	type restoreOutcome struct {
76		targetDir   string
77		assets      int
78		attachments int
79	}
80	
81	// restoreTestHooks 汇集还原流程中仅供同包回归测试使用的最小接缝：各字段默认
82	// 为 nil，还原始终执行真实的读写与文件系统操作，不提供任何用户可见的开关，
83	// CLI 参数、包格式与输出均与此无关。接缝只在真实操作对应的位置被调用，
84	// 测试借此确定性地令“这一次”真实操作失败（一般先制造真实的文件系统状态，
85	// 再由真实操作本身返回错误），而不是在入口直接返回错误或以模拟还原代替。
86	type restoreTestHooks struct {
87		// writeFault 在 writeAtomicFile 创建临时文件后、正式写入内容前按目标
88		// 路径调用；返回非 nil 时按真实写入失败处理（关闭并删除临时文件）。
89		// 接缝可先向 tmp 写入部分真实字节，模拟“写了一半后失败”。
90		writeFault func(path string, tmp *os.File, data []byte) error
91		// beforeMkdirAttach 在暂存目录内创建资料子目录的真实 MkdirAll 之前调用。
92		beforeMkdirAttach func(stage string)
93		// beforePreVerify 在发布前复核（真实的 loadStore 与副本校验值核对）之前调用。
94		beforePreVerify func(stage string)
95		// beforePublish 在暂存目录整体改名发布（真实 os.Rename）之前调用。
96		beforePublish func(stage, target string)
97		// beforePostVerify 在发布后复核（真实 openSourceStore 与资料可读性检查）
98		// 之前调用，此时目标目录已由真实改名发布生成。
99		beforePostVerify func(target string)
100	}
101	
102	// restoreFault 为包内测试接缝的当前配置；生产路径恒为 nil，行为与无接缝一致。
103	// 同包测试顺序执行，用例结束必须恢复为 nil，避免污染重试与其他测试。
104	var restoreFault *restoreTestHooks
105	
106	// fileMemberName 生成第 i（从 1 起）个资料成员的包内名称。
107	func fileMemberName(i int) string {
108		return fmt.Sprintf("%s/f%06d", migrateFilesDir, i)
109	}
110	
111	var fileMemberPattern = regexp.MustCompile(`^files/f[0-9]+$`)
112	
113	// sha256Hex 返回数据的 SHA-256 小写十六进制摘要。
114	func sha256Hex(data []byte) string {
115		sum := sha256.Sum256(data)
116		return hex.EncodeToString(sum[:])
117	}
118	
119	// dedupeStrings 按首次出现顺序去重。
120	func dedupeStrings(in []string) []string {
121		seen := map[string]bool{}
122		out := make([]string, 0, len(in))
123		for _, v := range in {
124			if !seen[v] {
125				seen[v] = true
126				out = append(out, v)
127			}
128		}
129		return out
130	}
131	
132	// selectLedgerData 从源台账中抽取所选资产及其全部工单、请求绑定、履历、
133	// 保养计划、备件领用记录与附件索引，组成一份独立的新台账数据。编号、序号、
134	// 计数器与全部业务内容原样保留，不做任何重编号。返回的切片均为新分配，
135	// 修改结果不会影响源台账。第三返回值为按登记履历序号排序的所选附件索引。
136	func selectLedgerData(src *store, ids []string) (*storeData, map[string]bool, []*Attachment) {
137		selected := map[string]bool{}
138		for _, id := range ids {
139			selected[id] = true
140		}
141		d := newStoreData()
142		for _, a := range src.data.Assets {
143			if selected[a.ID] {
144				na := *a
145				d.Assets = append(d.Assets, &na)
146			}
147		}
148		ticketIDs := map[string]bool{}
149		for _, t := range src.data.Tickets {
150			if selected[t.AssetID] {
151				nt := *t
152				d.Tickets = append(d.Tickets, &nt)
153				ticketIDs[t.ID] = true
154			}
155		}
156		for _, r := range src.data.Requests {
157			if ticketIDs[r.TicketID] {
158				d.Requests = append(d.Requests, r)
159			}
160		}
161		for _, e := range src.data.Events {
162			if selected[e.AssetID] {
163				d.Events = append(d.Events, e)
164			}
165		}
166		for _, p := range src.data.Plans {
167			if selected[p.AssetID] {
168				np := *p
169				d.Plans = append(d.Plans, &np)
170			}
171		}
172		for _, p := range src.data.Parts {
173			if ticketIDs[p.TicketID] {
174				np := *p
175				d.Parts = append(d.Parts, &np)
176			}
177		}
178		for _, a := range src.data.Attachments {
179			if ticketIDs[a.TicketID] {
180				na := *a
181				d.Attachments = append(d.Attachments, &na)
182			}
183		}
184		// 计数器原样保留：迁移包内各类编号、履历序号与计数器均与源一致。
185		d.NextTicketSeq = src.data.NextTicketSeq
186		d.NextPartSeq = src.data.NextPartSeq
187		d.NextAttachSeq = src.data.NextAttachSeq
188	
189		regSeqs := src.attachRegSeqs()
190		attachments := make([]*Attachment, len(d.Attachments))
191		copy(attachments, d.Attachments)
192		sort.SliceStable(attachments, func(i, j int) bool {
193			return regSeqs[attachments[i].ID] < regSeqs[attachments[j].ID]
194		})
195		return d, ticketIDs, attachments
196	}
197	
198	// buildMigrationZip 序列化台账并把每份资料连同清单写入 zip。资料内容由
199	// contents 提供（按 attachments 顺序，每条索引一项；同路径多条索引各自
200	// 独立）。zip 先写入 w 指向的临时文件，成功后由调用方原子改名发布。
201	func buildMigrationZip(w io.Writer, ledger []byte, assetCount int, attachments []*Attachment, contents [][]byte) error {
202		zw := zip.NewWriter(w)
203		writeMember := func(name string, data []byte) error {
204			fh := &zip.FileHeader{
205				Name:   name,
206				Method: zip.Deflate,
207			}
208			fh.SetMode(0o644)
209			f, err := zw.CreateHeader(fh)
210			if err != nil {
211				return err
212			}
213			if _, err := f.Write(data); err != nil {
214				return err
215			}
216			return nil
217		}
218		if err := writeMember(migrateLedgerName, ledger); err != nil {
219			return fmt.Errorf("写入台账成员失败: %w", err)
220		}
221		metas := make([]migrateFileMeta, 0, len(attachments))
222		for i, a := range attachments {
223			name := fileMemberName(i + 1)
224			if err := writeMember(name, contents[i]); err != nil {
225				return fmt.Errorf("写入资料成员失败（附件编号 %s）: %w", a.ID, err)
226			}
227			metas = append(metas, migrateFileMeta{
228				AttachmentID: a.ID,
229				Member:       name,
230				Size:         int64(len(contents[i])),
231				SHA256:       sha256Hex(contents[i]),
232			})
233		}
234		manifest := migrateManifest{
235			Format:          migrateMagic + "/1",
236			Version:         migrateVersion,
237			Ledger:          migrateLedgerName,
238			LedgerSize:      int64(len(ledger)),
239			LedgerSHA256:    sha256Hex(ledger),
240			Files:           metas,
241			AssetCount:      assetCount,
242			AttachmentCount: len(metas),
243		}
244		var mbuf bytes.Buffer
245		enc := json.NewEncoder(&mbuf)
246		enc.SetIndent("", "  ")
247		if err := enc.Encode(manifest); err != nil {
248			return fmt.Errorf("编码清单失败: %w", err)
249		}
250		if err := writeMember(migrateManifestName, mbuf.Bytes()); err != nil {
251			return fmt.Errorf("写入清单成员失败: %w", err)
252		}
253		if err := zw.Close(); err != nil {
254			return fmt.Errorf("写入迁移包失败: %w", err)
255		}
256		return nil
257	}
258	
259	// exportPackage 把 dataDir 中所选资产打包到 packagePath。源台账与原资料
260	// 只读；包文件路径已存在、资产未知、源台账矛盾、任一资料不是可读普通文件
261	// 或读写失败时整次拒绝，不留下成品包，也不修改源目录任何字节。
262	func exportPackage(dataDir, packagePath string, assetIDs []string) (*exportOutcome, error) {
263		absPkg, err := filepath.Abs(packagePath)
264		if err != nil {
265			return nil, fmt.Errorf("无法解析迁移包路径 %q: %w", packagePath, err)
266		}
267		// 已有包文件（含目录、符号链接等任何同名路径）不得覆盖。
268		if _, err := os.Lstat(absPkg); err == nil {
269			return nil, fmt.Errorf("迁移包文件 %s 已存在，拒绝覆盖，请另选路径", absPkg)
270		} else if !errors.Is(err, os.ErrNotExist) {
271			return nil, fmt.Errorf("无法访问迁移包路径 %s: %w", absPkg, err)
272		}
273	
274		// 源台账必须已存在并通过整库一致性检查；源始终只读。
275		src, err := openSourceStore(dataDir)
276		if err != nil {
277			return nil, err
278		}
279		ids := dedupeStrings(assetIDs)
280		for _, id := range ids {
281			if src.findAsset(id) == nil {
282				return nil, fmt.Errorf("%w: 源台账中不存在资产编号 %q", errNotFound, id)
283			}
284		}
285	
286		d, _, attachments := selectLedgerData(src, ids)
287		if err := validateData(d); err != nil {
288			return nil, fmt.Errorf("所选数据的业务关联校验失败，拒绝打包: %w", err)
289		}
290	
291		// 每条附件索引（含已撤销）指向的资料当前都必须是可读普通文件；同路径的
292		// 多条索引逐一独立读取，各成一个成员。任一不可用则整次拒绝，不打包。
293		contents := make([][]byte, len(attachments))
294		for i, a := range attachments {
295			if err := checkAttachFile(a.Path); err != nil {
296				return nil, fmt.Errorf("附件编号 %s 指向的资料不可打包: %v", a.ID, err)
297			}
298			raw, rerr := os.ReadFile(a.Path)
299			if rerr != nil {
300				return nil, fmt.Errorf("读取附件编号 %s 的资料 %s 失败: %w", a.ID, a.Path, rerr)
301			}
302			contents[i] = raw
303		}
304	
305		ledger, err := encodeLedger(d)
306		if err != nil {
307			return nil, err
308		}
309		assetCount := len(d.Assets)
310	
311		// 先写同目录临时文件，全部成功并 Sync 后 rename 发布；任何失败都删除
312		// 临时文件，绝不在目标路径留下成品包或半成品。
313		dir := filepath.Dir(absPkg)
314		if err := os.MkdirAll(dir, 0o755); err != nil {
315			return nil, fmt.Errorf("创建迁移包所在目录失败: %w", err)
316		}
317		tmp, err := os.CreateTemp(dir, ".caretrack-pkg-*.zip.tmp")
318		if err != nil {
319			return nil, fmt.Errorf("创建临时迁移包失败: %w", err)
320		}
321		tmpName := tmp.Name()
322		cleanup := func() { _ = os.Remove(tmpName) }
323		if err := buildMigrationZip(tmp, ledger, assetCount, attachments, contents); err != nil {
324			_ = tmp.Close()
325			cleanup()
326			return nil, err
327		}
328		if err := tmp.Sync(); err != nil {
329			_ = tmp.Close()
330			cleanup()
331			return nil, fmt.Errorf("写入迁移包失败: %w", err)
332		}
333		if err := tmp.Close(); err != nil {
334			cleanup()
335			return nil, fmt.Errorf("写入迁移包失败: %w", err)
336		}
337		if err := os.Rename(tmpName, absPkg); err != nil {
338			cleanup()
339			return nil, fmt.Errorf("保存迁移包失败: %w", err)
340		}
341		out := &exportOutcome{
342			packagePath: absPkg,
343			assetIDs:    ids,
344			attachments: len(attachments),
345		}
346		return out, nil
347	}
