349	// encodeLedger 以与 store.save 相同的缩进 JSON 形式编码台账数据。
350	func encodeLedger(d *storeData) ([]byte, error) {
351		d.EventsJSON = make([]eventJSON, len(d.Events))
352		for i, e := range d.Events {
353			d.EventsJSON[i] = e.toJSON()
354		}
355		if err := validateData(d); err != nil {
356			return nil, fmt.Errorf("待打包数据未通过一致性检查: %w", err)
357		}
358		var buf bytes.Buffer
359		enc := json.NewEncoder(&buf)
360		enc.SetIndent("", "  ")
361		if err := enc.Encode(d); err != nil {
362			return nil, fmt.Errorf("编码台账失败: %w", err)
363		}
364		return buf.Bytes(), nil
365	}
