367	// decodePackageLedger 解析包内台账 JSON 并转换履历、补齐旧库缺省段，
368	// 不做任何写盘。
369	func decodePackageLedger(raw []byte) (*storeData, error) {
370		var d storeData
371		if err := json.Unmarshal(raw, &d); err != nil {
372			return nil, fmt.Errorf("包内台账无法解析: %w", err)
373		}
374		if d.EventsJSON != nil {
375			d.Events = make([]Event, len(d.EventsJSON))
376			for i, ej := range d.EventsJSON {
377				ev, err := ej.toEvent()
378				if err != nil {
379					return nil, fmt.Errorf("包内台账履历无效: %w", err)
380				}
381				d.Events[i] = ev
382			}
383		}
384		if d.Plans == nil {
385			d.Plans = []*Plan{}
386		}
387		if d.Parts == nil {
388			d.Parts = []*PartWithdrawal{}
389		}
390		if d.NextPartSeq == 0 && len(d.Parts) == 0 {
391			d.NextPartSeq = 1
392		}
393		if d.Attachments == nil {
394			d.Attachments = []*Attachment{}
395		}
396		if d.NextAttachSeq == 0 && len(d.Attachments) == 0 {
397			d.NextAttachSeq = 1
398		}
399		return &d, nil
400	}
