402	// readZipMember 读取一个 zip 成员的全部内容。
403	func readZipMember(f *zip.File) ([]byte, error) {
404		rc, err := f.Open()
405		if err != nil {
406			return nil, err
407		}
408		defer rc.Close()
409		return io.ReadAll(rc)
410	}
