412	// verifyPackage 完整核对迁移包：包格式与版本、成员集合（无缺失、额外、重复
413	// 成员）、成员类型（仅普通文件，拒绝目录与链接）、成员名（拒绝越界路径）、
414	// 台账格式与业务关联、资料映射、实际成员与内容校验值。任何问题都返回说明
415	// 原因的错误。核对全程只读包文件，不写出任何内容。
416	//
417	// 返回台账数据、附件索引到资料成员名的映射与成员内容（键为成员名）。
418	func verifyPackage(zr *zip.Reader) (*storeData, map[string]string, map[string][]byte, error) {
419		// 成员清单核对：名称唯一、仅普通文件、成员名不越界。
420		members := map[string]*zip.File{}
421		for _, f := range zr.File {
422			name := filepath.ToSlash(f.Name)
423			if name == "" || strings.HasPrefix(name, "/") || strings.HasPrefix(name, "../") ||
424				name == ".." || strings.Contains(name, "/../") || strings.HasSuffix(name, "/..") ||
425				strings.Contains(name, "\\") {
426				return nil, nil, nil, fmt.Errorf("迁移包含有越界成员路径 %q，整包拒绝", f.Name)
427			}
428			if !f.Mode().IsRegular() {
429				return nil, nil, nil, fmt.Errorf("迁移包成员 %s 不是普通文件（拒绝目录或链接成员）", name)
430			}
431			if members[name] != nil {
432				return nil, nil, nil, fmt.Errorf("迁移包成员 %s 重复，整包拒绝", name)
433			}
434			members[name] = f
435		}
436	
437		manifestFile := members[migrateManifestName]
438		if manifestFile == nil {
439			return nil, nil, nil, fmt.Errorf("迁移包缺少清单成员 %s", migrateManifestName)
440		}
441		manifestRaw, err := readZipMember(manifestFile)
442		if err != nil {
443			return nil, nil, nil, fmt.Errorf("读取清单失败: %w", err)
444		}
445		var manifest migrateManifest
446		// 宽容解析（忽略未知字段）：包的版本判断必须优先于字段差异，未来版本的
447		// 包须报“未知版本”原因，而不是笼统的格式错误。包内实际成员集合另按
448		// 严格枚举核对，未知字段不会产生任何成员或写出。
449		if err := json.Unmarshal(manifestRaw, &manifest); err != nil {
450			return nil, nil, nil, fmt.Errorf("清单格式无效: %w", err)
451		}
452		if manifest.Format != migrateMagic+"/1" {
453			return nil, nil, nil, fmt.Errorf("未知迁移包格式 %q（本工具支持 %s/1）", manifest.Format, migrateMagic)
454		}
455		if manifest.Version != migrateVersion {
456			return nil, nil, nil, fmt.Errorf("未知迁移包版本 %d：本工具仅支持版本 %d，整包拒绝", manifest.Version, migrateVersion)
457		}
458	
459		// 清单内资料映射自洽：附件编号与成员名均唯一，成员名合法。
460		wantFiles := map[string]bool{}
461		wantAttach := map[string]bool{}
462		for _, fm := range manifest.Files {
463			if fm.AttachmentID == "" || fm.Member == "" || fm.SHA256 == "" {
464				return nil, nil, nil, fmt.Errorf("清单中存在字段不完整的资料条目")
465			}
466			if wantAttach[fm.AttachmentID] {
467				return nil, nil, nil, fmt.Errorf("清单中附件编号 %s 的资料条目重复", fm.AttachmentID)
468			}
469			wantAttach[fm.AttachmentID] = true
470			if wantFiles[fm.Member] {
471				return nil, nil, nil, fmt.Errorf("清单中资料成员 %s 重复", fm.Member)
472			}
473			if !fileMemberPattern.MatchString(fm.Member) {
474				return nil, nil, nil, fmt.Errorf("清单中资料成员名 %q 不合法", fm.Member)
475			}
476			wantFiles[fm.Member] = true
477		}
478	
479		// 实际成员集合必须恰为 {清单, 台账} ∪ 清单所列资料成员：无缺失、无额外。
480		wantMembers := map[string]bool{migrateManifestName: true}
481		if manifest.Ledger != migrateLedgerName {
482			return nil, nil, nil, fmt.Errorf("清单声明的台账成员名为 %q，与约定 %q 不符", manifest.Ledger, migrateLedgerName)
483		}
484		wantMembers[migrateLedgerName] = true
485		for name := range wantFiles {
486			wantMembers[name] = true
487		}
488		if len(members) != len(wantMembers) {
489			return nil, nil, nil, fmt.Errorf("迁移包成员数量不符：应有 %d 个，实际 %d 个（存在缺失或额外成员）",
490				len(wantMembers), len(members))
491		}
492		for name := range wantMembers {
493			if members[name] == nil {
494				return nil, nil, nil, fmt.Errorf("迁移包缺少成员 %s", name)
495			}
496		}
497		for name := range members {
498			if !wantMembers[name] {
499				return nil, nil, nil, fmt.Errorf("迁移包含有清单之外的额外成员 %s", name)
500			}
501		}
502	
503		// 台账内容校验值、格式与整库业务关联。
504		ledgerRaw, err := readZipMember(members[migrateLedgerName])
505		if err != nil {
506			return nil, nil, nil, fmt.Errorf("读取台账成员失败: %w", err)
507		}
508		if int64(len(ledgerRaw)) != manifest.LedgerSize || sha256Hex(ledgerRaw) != manifest.LedgerSHA256 {
509			return nil, nil, nil, fmt.Errorf("台账成员内容损坏：大小或校验值与清单不符")
510		}
511		d, err := decodePackageLedger(ledgerRaw)
512		if err != nil {
513			return nil, nil, nil, err
514		}
515		if err := validateData(d); err != nil {
516			return nil, nil, nil, fmt.Errorf("包内台账业务关联校验失败: %w", err)
517		}
518		// 清单汇总数量须与台账实际成员一致。
519		if manifest.AssetCount != len(d.Assets) {
520			return nil, nil, nil, fmt.Errorf("清单资产数量 %d 与台账实际 %d 不符",
521				manifest.AssetCount, len(d.Assets))
522		}
523		if manifest.AttachmentCount != len(d.Attachments) {
524			return nil, nil, nil, fmt.Errorf("清单附件索引数量 %d 与台账实际 %d 不符",
525				manifest.AttachmentCount, len(d.Attachments))
526		}
527	
528		// 资料映射核对：每条附件索引恰有一个资料成员，每个资料成员恰对应一条
529		// 附件索引；成员内容的大小与 SHA-256 与清单一致（zip 读取本身已校验 CRC）。
530		attachByID := map[string]*Attachment{}
531		for _, a := range d.Attachments {
532			attachByID[a.ID] = a
533		}
534		if len(attachByID) != len(d.Attachments) {
535			return nil, nil, nil, fmt.Errorf("包内台账附件编号重复")
536		}
537		if len(manifest.Files) != len(d.Attachments) {
538			return nil, nil, nil, fmt.Errorf("资料成员数量（%d）与附件索引数量（%d）不符",
539				len(manifest.Files), len(d.Attachments))
540		}
541		attachMember := map[string]string{}
542		contents := map[string][]byte{}
543		for _, fm := range manifest.Files {
544			if attachByID[fm.AttachmentID] == nil {
545				return nil, nil, nil, fmt.Errorf("资料成员 %s 对应的附件编号 %s 在台账中不存在",
546					fm.Member, fm.AttachmentID)
547			}
548			raw, err := readZipMember(members[fm.Member])
549			if err != nil {
550				return nil, nil, nil, fmt.Errorf("读取资料成员 %s 失败: %w", fm.Member, err)
551			}
552			if int64(len(raw)) != fm.Size || sha256Hex(raw) != fm.SHA256 {
553				return nil, nil, nil, fmt.Errorf("资料成员 %s（附件编号 %s）内容损坏：大小或校验值不符",
554					fm.Member, fm.AttachmentID)
555			}
556			attachMember[fm.AttachmentID] = fm.Member
557			contents[fm.Member] = raw
558		}
559		return d, attachMember, contents, nil
560	}
