562	// writeAtomicFile 在 dir 下经临时文件 + rename 原子写入一个普通文件，
563	// 权限 0644；失败由调用方负责清理暂存目录。
564	func writeAtomicFile(path string, data []byte) error {
565		dir := filepath.Dir(path)
566		tmp, err := os.CreateTemp(dir, ".caretrack-restore-*.tmp")
567		if err != nil {
568			return err
569		}
570		tmpName := tmp.Name()
571		// 测试接缝：在真实内容写入之前插入；返回错误时与真实写入失败走同一条
572		// 清理路径（关闭并删除临时文件）。默认无接缝时此处不产生任何行为差异。
573		if restoreFault != nil && restoreFault.writeFault != nil {
574			if ferr := restoreFault.writeFault(path, tmp, data); ferr != nil {
575				_ = tmp.Close()
576				_ = os.Remove(tmpName)
577				return ferr
578			}
579		}
580		if _, err := tmp.Write(data); err != nil {
581			_ = tmp.Close()
582			_ = os.Remove(tmpName)
583			return err
584		}
585		if err := tmp.Sync(); err != nil {
586			_ = tmp.Close()
587			_ = os.Remove(tmpName)
588			return err
589		}
590		if err := tmp.Close(); err != nil {
591			_ = os.Remove(tmpName)
592			return err
593		}
594		if err := os.Chmod(tmpName, 0o644); err != nil {
595			_ = os.Remove(tmpName)
596			return err
597		}
598		if err := os.Rename(tmpName, path); err != nil {
599			_ = os.Remove(tmpName)
600			return err
601		}
602		return nil
603	}
604	
605	// restorePackage 从迁移包在尚不存在的 targetDir 还原数据：先在目标的同级
606	// 暂存目录内建立台账与独立资料副本（附件记录及登记、撤销履历中的路径同步
607	// 替换为副本的绝对路径），全部写入并复核后才整体改名发布为目标目录。任何
608	// 失败都不留下目标目录或部分资料；输入包与原数据字节保持，可用原包重试。
609	func restorePackage(packagePath, targetDir string) (*restoreOutcome, error) {
610		absPkg, err := filepath.Abs(packagePath)
611		if err != nil {
612			return nil, fmt.Errorf("无法解析迁移包路径 %q: %w", packagePath, err)
613		}
614		absTarget, err := filepath.Abs(targetDir)
615		if err != nil {
616			return nil, fmt.Errorf("无法解析目标数据目录 %q: %w", targetDir, err)
617		}
618		// 目标目录（或任何同名路径）已存在即拒绝。
619		if _, err := os.Lstat(absTarget); err == nil {
620			return nil, fmt.Errorf("目标数据目录 %s 已存在，拒绝覆盖，请选择尚不存在的目录", absTarget)
621		} else if !errors.Is(err, os.ErrNotExist) {
622			return nil, fmt.Errorf("无法访问目标数据目录 %s: %w", absTarget, err)
623		}
624	
625		// 迁移包须为可读普通文件；只读打开，绝不写回。
626		pf, err := os.Open(absPkg)
627		if err != nil {
628			return nil, fmt.Errorf("无法打开迁移包 %s: %w", absPkg, err)
629		}
630		fi, err := pf.Stat()
631		if err != nil {
632			_ = pf.Close()
633			return nil, fmt.Errorf("无法读取迁移包 %s: %w", absPkg, err)
634		}
635		if !fi.Mode().IsRegular() {
636			_ = pf.Close()
637			return nil, fmt.Errorf("迁移包 %s 不是普通文件", absPkg)
638		}
639		zr, err := zip.NewReader(pf, fi.Size())
640		if err != nil {
641			_ = pf.Close()
642			return nil, fmt.Errorf("迁移包 %s 不是有效的包格式: %w", absPkg, err)
643		}
644		// 提交前完整核对：格式、版本、业务关联、资料映射、实际成员与校验值。
645		d, attachMember, contents, err := verifyPackage(zr)
646		if err != nil {
647			_ = pf.Close()
648			return nil, err
649		}
650		if err := pf.Close(); err != nil {
651			return nil, fmt.Errorf("读取迁移包失败: %w", err)
652		}
653	
654		// 附件路径替换映射：副本将位于目标目录内的 attachments/ 子目录，文件名
655		// 沿用包内生成名；这些路径均由工具生成，绝不取自包内原绝对路径，也不会
656		// 按原路径访问外部资料。
657		newPath := map[string]string{}
658		for _, a := range d.Attachments {
659			base := filepath.Base(attachMember[a.ID])
660			np := filepath.Join(absTarget, restoreAttachDir, base)
661			newPath[a.ID] = np
662		}
663		for _, a := range d.Attachments {
664			a.Path = newPath[a.ID]
665		}
666		// 登记与撤销履历中的路径同步替换（validateData 已保证履历路径与记录一致，
667		// 替换后其余身份与业务含义保持，不新增任何履历）。
668		for i := range d.Events {
669			e := &d.Events[i]
670			if (e.Kind == eventAttach || e.Kind == eventAttachRevoke) && e.AttachmentID != "" {
671				if np := newPath[e.AttachmentID]; np != "" {
672					e.Path = np
673				}
674			}
675		}
676		if err := validateData(d); err != nil {
677			return nil, fmt.Errorf("替换资料路径后台账校验失败: %w", err)
678		}
679		ledger, err := encodeLedger(d)
680		if err != nil {
681			return nil, err
682		}
683	
684		// 在目标同级建立暂存目录，所有写入完成并复核后整体 rename 发布；
685		// 任何失败都删除暂存目录并确保目标路径不存在。
686		parent := filepath.Dir(absTarget)
687		if err := os.MkdirAll(parent, 0o755); err != nil {
688			return nil, fmt.Errorf("创建目标父目录失败: %w", err)
689		}
690		stage, err := os.MkdirTemp(parent, ".caretrack-restore-*")
691		if err != nil {
692			return nil, fmt.Errorf("创建暂存目录失败: %w", err)
693		}
694		abort := func(err error) (*restoreOutcome, error) {
695			_ = os.RemoveAll(stage)
696			_ = os.RemoveAll(absTarget)
697			return nil, err
698		}
699		if restoreFault != nil && restoreFault.beforeMkdirAttach != nil {
700			restoreFault.beforeMkdirAttach(stage)
701		}
702		if err := os.MkdirAll(filepath.Join(stage, restoreAttachDir), 0o755); err != nil {
703			return abort(fmt.Errorf("创建资料目录失败: %w", err))
704		}
705		if err := writeAtomicFile(filepath.Join(stage, dataFileName), ledger); err != nil {
706			return abort(fmt.Errorf("写入台账失败: %w", err))
707		}
708		// 资料副本：逐份写入，成员名由工具生成，全部限制在暂存目录（发布后即
709		// 目标目录）之内。
710		for _, a := range d.Attachments {
711			member := attachMember[a.ID]
712			dst := filepath.Join(stage, restoreAttachDir, filepath.Base(member))
713			if err := writeAtomicFile(dst, contents[member]); err != nil {
714				return abort(fmt.Errorf("写入资料副本失败（附件编号 %s）: %w", a.ID, err))
715			}
716		}
717		// 发布前在暂存目录内复核：台账可加载且业务自洽，每份资料为与包内一致的
718		// 普通文件（内容校验值相符）。
719		if restoreFault != nil && restoreFault.beforePreVerify != nil {
720			restoreFault.beforePreVerify(stage)
721		}
722		checkStore, err := loadStore(stage, false)
723		if err != nil {
724			return abort(fmt.Errorf("暂存台账复核失败: %w", err))
725		}
726		for _, a := range checkStore.data.Attachments {
727			member := attachMember[a.ID]
728			path := filepath.Join(stage, restoreAttachDir, filepath.Base(member))
729			raw, rerr := os.ReadFile(path)
730			if rerr != nil {
731				return abort(fmt.Errorf("资料副本复核失败（附件编号 %s）: %w", a.ID, rerr))
732			}
733			if sha256Hex(raw) != sha256Hex(contents[member]) {
734				return abort(fmt.Errorf("资料副本（附件编号 %s）复核校验值不符", a.ID))
735			}
736		}
737		// 整体发布：暂存目录原子改名为目标目录。
738		if restoreFault != nil && restoreFault.beforePublish != nil {
739			restoreFault.beforePublish(stage, absTarget)
740		}
741		if err := os.Rename(stage, absTarget); err != nil {
742			return abort(fmt.Errorf("发布目标目录失败: %w", err))
743		}
744		// 发布后再复核一次：台账可加载、资料副本为可读普通文件。全部就绪后才
745		// 向调用方报告成功；失败则移除目标目录。
746		if restoreFault != nil && restoreFault.beforePostVerify != nil {
747			restoreFault.beforePostVerify(absTarget)
748		}
749		final, err := openSourceStore(absTarget)
750		if err != nil {
751			_ = os.RemoveAll(absTarget)
752			return nil, fmt.Errorf("还原后复核失败: %w", err)
753		}
754		for _, a := range final.data.Attachments {
755			if !attachmentReadable(a.Path) {
756				_ = os.RemoveAll(absTarget)
757				return nil, fmt.Errorf("还原后复核失败：附件编号 %s 的资料副本不可读", a.ID)
758			}
759		}
760		return &restoreOutcome{
761			targetDir:   absTarget,
762			assets:      len(final.data.Assets),
763			attachments: len(final.data.Attachments),
764		}, nil
765	}
766	
767	// cmdExport 为“导出迁移包”命令处理：输入数据目录、非空资产编号列表与包
768	// 文件路径。源台账与原资料只读，已有包文件不得覆盖，任何失败不留成品包。
769	func cmdExport(args []string, w io.Writer) error {
770		var opts cmdOptions
771		var packagePath string
772		var assetIDs stringListFlag
773		fs := newFlagSet("export", &opts)
774		fs.StringVar(&packagePath, "package", "", "迁移包文件路径（必填；已存在则拒绝，不会覆盖）")
775		fs.Var(&assetIDs, "asset-id", "要打包的资产编号（必填，可重复；重复编号按一项处理）")
776		if err := parseFlags(fs, args); err != nil {
777			return err
778		}
779		if err := requireFlag(fs, packagePath, "package"); err != nil {
780			return err
781		}
782		if len(assetIDs) == 0 {
783			return &usageError{msg: "命令 export 缺少必填参数 --asset-id（至少一项资产编号）"}
784		}
785		for _, id := range assetIDs {
786			if id == "" {
787				return &usageError{msg: "命令 export 的 --asset-id 不能为空"}
788			}
789		}
790	
791		outcome, err := exportPackage(opts.dataDir, packagePath, []string(assetIDs))
792		if err != nil {
793			return err
794		}
795		fmt.Fprintf(w, "迁移包已生成: %s\n", outcome.packagePath)
796		fmt.Fprintf(w, "所选资产: %d 项（%s）\n", len(outcome.assetIDs), strings.Join(outcome.assetIDs, ", "))
797		fmt.Fprintf(w, "附件索引: %d 条\n", outcome.attachments)
798		return nil
799	}
800	
801	// cmdRestore 为“包还原”命令处理：输入包路径和尚不存在的目标数据目录。
802	// 在目标内建立独立资料副本，路径同步替换为副本绝对路径；失败不留目标。
803	func cmdRestore(args []string, w io.Writer) error {
804		fs := flag.NewFlagSet("restore", flag.ContinueOnError)
805		fs.SetOutput(os.Stdout)
806		fs.Usage = func() {
807			fmt.Fprintf(os.Stdout, "用法: caretrack restore --package 包文件 --target-dir 目录\n\n")
808			fs.PrintDefaults()
809		}
810		var packagePath, targetDir string
811		fs.StringVar(&packagePath, "package", "", "迁移包文件路径（必填）")
812		fs.StringVar(&targetDir, "target-dir", "", "要创建的目标数据目录（必填；必须尚不存在）")
813		if err := parseFlags(fs, args); err != nil {
814			return err
815		}
816		if err := requireFlag(fs, packagePath, "package"); err != nil {
817			return err
818		}
819		if err := requireFlag(fs, targetDir, "target-dir"); err != nil {
820			return err
821		}
822	
823		outcome, err := restorePackage(packagePath, targetDir)
824		if err != nil {
825			return err
826		}
827		fmt.Fprintf(w, "迁移包已还原: %s\n", outcome.targetDir)
828		fmt.Fprintf(w, "资产: %d 项\n", outcome.assets)
829		fmt.Fprintf(w, "附件索引: %d 条\n", outcome.attachments)
830		return nil
831	}
