7	// 设备位置变更与工单报修地点追溯。
8	//
9	// 变更入口输入资产编号、新位置与非空理由；可用、维修中、停用资产均可变更。
10	// 未知资产、空位置或理由、新位置与当前位置相同均拒绝。成功后更新资产当前
11	// 位置，并追加一条资产级履历，含原位置、新位置、理由、时间与全库履历序号。
12	// 位置变更不改变资产状态、工单状态、负责人、请求绑定、保养周期、备件、附件
13	// 及停机统计：维修中搬移不改旧工单的报修地点，搬移后新报修采用新地点。
14	//
15	// 每张工单的报修地点在报修时按当时资产位置确定（Ticket.ReportLocation），
16	// 之后只能由履历链按全库序号追溯：不能用当前地点、履历时间或数组位置代替。
17	// 旧请求重放仍返回原工单，不改地点也不追加履历。
18	//
19	// 首次变更前的位置就是最早一条位置变更履历记录的原位置，重载后仍可还原；
20	// 没有位置履历的有效旧库以资产保存位置作为起点，无需转换，查询不补写数据。
21	// 加载与保存按履历序号重放核对位置链：归属资产存在、原位置接续当时位置、
22	// 新位置非空且与原位置不同，最终位置与资产保存值一致。数组乱序、序号间隔、
23	// 时间不递增仍合法；位置矛盾时所有读写命令退出 1 并指出“位置矛盾”类别，
24	// 原文件不变，不自动修复。
25	//
26	// 变更为一次原子保存：校验、履历容量不足或读写失败时不留部分位置或履历、
27	// 不消耗序号，原文件字节保持，恢复后可按原输入重试。
28	
29	// appendRelocateEvent 以给定序号追加位置变更履历。该履历为资产级履历，
30	// 不属于任何工单；from/to 为原位置与新位置，content 为变更理由。
31	func (s *store) appendRelocateEvent(seq int, assetID, from, to, reason string) {
32		s.data.Events = append(s.data.Events, Event{
33			Seq:     seq,
34			AssetID: assetID,
35			Kind:    eventRelocate,
36			Content: reason,
37			From:    from,
38			To:      to,
39			Time:    s.now(),
40		})
41	}
42	
43	// relocateAsset 变更资产当前位置：可用、维修中、停用资产均可变更。
44	// 未知资产、空位置或理由、新位置与当前位置相同均拒绝；位置变更不改变资产
45	// 状态、工单、负责人、请求绑定、保养周期、备件、附件及停机统计。
46	// 返回更新后的资产与原位置。失败路径不修改任何业务数据。
47	func (s *store) relocateAsset(assetID, newLocation, reason string) (*Asset, string, error) {
48		a := s.findAsset(assetID)
49		if a == nil {
50			return nil, "", fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
51		}
52		if newLocation == "" {
53			return nil, "", fmt.Errorf("%w: 新位置不能为空", errConflict)
54		}
55		if reason == "" {
56			return nil, "", fmt.Errorf("%w: 位置变更理由不能为空", errConflict)
57		}
58		if a.Location == newLocation {
59			return nil, "", fmt.Errorf("%w: 资产 %s 当前位置已是 %s，不能变更为相同位置",
60				errConflict, assetID, newLocation)
61		}
62		eventSeq, err := s.nextEventSeq()
63		if err != nil {
64			return nil, "", err
65		}
66		from := a.Location
67		a.Location = newLocation
68		s.appendRelocateEvent(eventSeq, assetID, from, newLocation, reason)
69		return a, from, nil
70	}
71	
72	// locationAtSeq 按全库履历序号追溯资产在序号 seq 当时的位置：取序号不大于
73	// seq 的最后一条位置变更履历的新位置；此前（含没有任何位置变更履历时）为
74	// 位置链起点。位置链起点为最早一条位置变更履历的原位置；没有位置履历时为
75	// 资产保存位置。判定只按履历序号，不用履历时间或数组位置。
76	func (s *store) locationAtSeq(assetID string, seq int) string {
77		current := s.locationOrigin(assetID)
78		best := 0
79		for _, e := range s.data.Events {
80			if e.AssetID != assetID || e.Kind != eventRelocate {
81				continue
82			}
83			if e.Seq <= seq && e.Seq > best {
84				best = e.Seq
85				current = e.To
86			}
87		}
88		return current
89	}
90	
91	// locationOrigin 返回资产位置链起点：有位置变更履历时为最早一条（按全库
92	// 序号）履历的原位置；没有位置履历时为资产保存位置。
93	func (s *store) locationOrigin(assetID string) string {
94		origin := ""
95		minSeq := 0
96		found := false
97		for _, e := range s.data.Events {
98			if e.AssetID != assetID || e.Kind != eventRelocate {
99				continue
100			}
101			if !found || e.Seq < minSeq {
102				origin = e.From
103				minSeq = e.Seq
104				found = true
105			}
106		}
107		if found {
108			return origin
109		}
110		if a := s.findAsset(assetID); a != nil {
111			return a.Location
112		}
113		return ""
114	}
115	
116	// reportLocationOf 返回工单报修履历序号当时的资产位置。工单保存了报修地点时
117	// 以保存值为准（加载校验已保证它与履历链一致）；缺少该字段的有效旧库工单
118	// 按履历序号现场追溯，查询不补写数据。
119	func (s *store) reportLocationOf(t *Ticket) string {
120		if t.ReportLocation != "" {
121			return t.ReportLocation
122		}
123		reportSeq := 0
124		for _, e := range s.data.Events {
125			if e.TicketID == t.ID && e.Kind == eventReport && e.Seq > reportSeq {
126				reportSeq = e.Seq
127			}
128		}
129		return s.locationAtSeq(t.AssetID, reportSeq)
130	}
