1	package main
2	
3	import (
4		"fmt"
5		"math"
6		"os"
7		"sort"
8	)
9	
10	// 维修工单本地资料附件索引。
11	//
12	// 只保存资料文件的引用（登记时解析得到的绝对路径），不复制、不修改、不删除
13	// 资料文件本身。登记输入工单编号、本地文件路径与非空说明；未关闭、已关闭或
14	// 已取消工单均可补充资料。登记时文件须为存在且可读的普通文件；文件日后消失、
15	// 成为目录或不可读仅使引用不可用，不阻止撤销及其他业务，也不参与整库一致性
16	// 校验。每次登记独立生成同目录唯一且不复用的附件编号（A 加补零序号），同路径
17	// 不合并，也不使用报修请求标识去重。
18	//
19	// 撤销输入附件编号与非空理由，保留记录、路径、说明与理由；未知编号、重复撤销
20	// 拒绝，不影响同路径其他索引或后来工单。工单终结不自动撤销附件；已撤销编号
21	// 不能恢复，可重新登记为新索引。登记、撤销各为一次原子保存：校验、编号或履历
22	// 容量不足、读写失败时保留原文件字节，不留下部分记录、不消耗编号，恢复后可重试。
23	
24	// findAttachment 按附件编号查找附件记录，不存在时返回 nil。
25	func (s *store) findAttachment(id string) *Attachment {
26		for _, a := range s.data.Attachments {
27			if a.ID == id {
28				return a
29			}
30		}
31		return nil
32	}
33	
34	// attachRegSeqs 返回每条附件编号对应的登记履历全库序号。附件编号只用于定位
35	// 记录：各条索引的先后由该条唯一登记履历的序号决定，与记录数组位置、编号
36	// 大小及履历时间无关（有效台账允许数组乱序、序号间隔、时间不递增）。
37	func (s *store) attachRegSeqs() map[string]int {
38		seqs := make(map[string]int, len(s.data.Attachments))
39		for _, e := range s.data.Events {
40			if e.Kind == eventAttach {
41				seqs[e.AttachmentID] = e.Seq
42			}
43		}
44		return seqs
45	}
46	
47	// attachmentsOf 按登记先后返回工单的全部附件记录（含已撤销）：顺序由每条
48	// 唯一登记履历的全库序号决定，不使用数组位置或编号大小。
49	func (s *store) attachmentsOf(ticketID string) []*Attachment {
50		seqs := s.attachRegSeqs()
51		out := make([]*Attachment, 0)
52		for _, a := range s.data.Attachments {
53			if a.TicketID == ticketID {
54				out = append(out, a)
55			}
56		}
57		sort.SliceStable(out, func(i, j int) bool { return seqs[out[i].ID] < seqs[out[j].ID] })
58		return out
59	}
60	
61	// checkAttachFile 校验登记时的资料文件：须为存在且可读的普通文件。
62	func checkAttachFile(path string) error {
63		fi, err := os.Stat(path)
64		if err != nil {
65			return fmt.Errorf("附件文件 %s 不存在或不可访问: %v", path, err)
66		}
67		if !fi.Mode().IsRegular() {
68			return fmt.Errorf("附件路径 %s 不是普通文件", path)
69		}
70		f, err := os.Open(path)
71		if err != nil {
72			return fmt.Errorf("附件文件 %s 不可读: %v", path, err)
73		}
74		return f.Close()
75	}
76	
77	// attachmentReadable 报告资料文件当前是否仍可作为普通文件读取。文件日后
78	// 消失、成为目录或不可读仅使引用不可用，不影响台账一致性与任何业务操作。
79	func attachmentReadable(path string) bool {
80		return checkAttachFile(path) == nil
81	}
82	
83	// appendAttachEvent 以给定序号追加附件履历（登记或撤销）。附件履历属于附件
84	// 记录所在的工单，from/to、保养与备件字段恒为空；content 为附件说明或撤销
85	// 理由，Path 为记录保存的绝对路径。
86	func (s *store) appendAttachEvent(seq int, a *Attachment, kind, content string) {
87		s.data.Events = append(s.data.Events, Event{
88			Seq:          seq,
89			AssetID:      a.AssetID,
90			TicketID:     a.TicketID,
91			Kind:         kind,
92			Content:      content,
93			AttachmentID: a.ID,
94			Path:         a.Path,
95			Time:         s.now(),
96		})
97	}
98	
99	// attach 为工单登记本地资料附件索引：未关闭、已关闭或已取消工单均可补充。
100	// 生成同目录唯一且不复用的附件编号，追加一条登记履历。path 须为调用方已
101	// 解析得到的绝对路径，且登记时须为存在且可读的普通文件。每次登记独立：
102	// 同路径不合并，不使用报修请求标识去重。失败路径不修改任何业务数据，
103	// 也不消耗附件编号。
104	func (s *store) attach(ticketID, path, note string) (*Attachment, error) {
105		t := s.findTicket(ticketID)
106		if t == nil {
107			return nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
108		}
109		if note == "" {
110			return nil, fmt.Errorf("%w: 附件说明不能为空", errConflict)
111		}
112		if err := checkAttachFile(path); err != nil {
113			return nil, err
114		}
115		// 先确认附件编号与履历计数器都能推进，再修改任何业务数据：
116		// 编号耗尽时拒绝登记，不消耗编号，也不产生履历。
117		seq := s.data.NextAttachSeq
118		if seq < 1 || seq == math.MaxInt {
119			return nil, fmt.Errorf("%w: 附件编号计数器已耗尽，无法分配新附件编号", errConflict)
120		}
121		eventSeq, err := s.nextEventSeq()
122		if err != nil {
123			return nil, err
124		}
125		a := &Attachment{
126			ID:       fmt.Sprintf("A%04d", seq),
127			TicketID: t.ID,
128			AssetID:  t.AssetID,
129			Path:     path,
130			Note:     note,
131		}
132		s.data.NextAttachSeq = seq + 1
133		s.data.Attachments = append(s.data.Attachments, a)
134		s.appendAttachEvent(eventSeq, a, eventAttach, note)
135		return a, nil
136	}
137	
138	// revokeAttachment 按附件编号撤销附件索引：保留记录、路径、说明与撤销理由，
139	// 追加一条撤销履历。已撤销编号不能恢复（可重新登记为新索引）；工单终结不
140	// 自动撤销附件，撤销也不受工单状态限制。失败路径不修改任何业务数据。
141	func (s *store) revokeAttachment(id, reason string) (*Attachment, error) {
142		a := s.findAttachment(id)
143		if a == nil {
144			return nil, fmt.Errorf("%w: 未知附件编号 %q", errNotFound, id)
145		}
146		if a.Revoked {
147			return nil, fmt.Errorf("%w: 附件 %s 已撤销，不能重复撤销", errConflict, id)
148		}
149		if reason == "" {
150			return nil, fmt.Errorf("%w: 撤销理由不能为空", errConflict)
151		}
152		eventSeq, err := s.nextEventSeq()
153		if err != nil {
154			return nil, err
155		}
156		a.Revoked = true
157		a.RevokeReason = reason
158		s.appendAttachEvent(eventSeq, a, eventAttachRevoke, reason)
159		return a, nil
160	}
