// hasSubmissions 报告工单是否已有提交履历（含已退回、已取消前的旧提交）。
func (s *store) hasSubmissions(ticketID string) bool {
	for _, e := range s.data.Events {
		if e.TicketID == ticketID && e.Kind == eventSubmit {
			return true
		}
	}
	return false
